VID.narration = {"look":{"bar":false},"scenes":[{"dur":9.288,"caps":[[0.5,8.51,"Lectures thirteen and fourteen. Multi-objective evolutionary algorithms. This is how to search for good trade-offs."]],"warp":[[0,0],[0.5,0.9],[9.288,4]]},{"dur":28.352,"caps":[[0.5,7.71,"The back turbine sits in the front one's wake."],[7.96,15.01,"Moving it further back gives it more power."],[15.26,20.15,"But the longer cable costs more money."],[20.4,27.21,"Cost and power pull against each other: a trade-off."]],"warp":[[0,0],[0.5,0.5],[7.96,3.6],[15.26,6.6],[20.4,9.2],[28.352,13]]},{"dur":25.1,"caps":[[0.5,6.27,"Each layout gets two scores: its cost and its power."],[6.52,14.13,"Layout A becomes one point, its objective vector: (20, 30)."],[14.38,19.03,"Layout E costs more but makes more power: (52, 70)."],[19.28,24.01,"Eleven layouts, eleven points. Better is up and to the left."]],"warp":[[0,0],[0.5,0.5],[6.52,3.4],[14.38,6.2],[19.28,8.8],[25.1,12]]},{"dur":28.282,"caps":[[0.5,4.03,"Compare two layouts, D and G."],[4.28,8.69,"D is cheaper and makes more power."],[8.94,15.67,"So D dominates G: no worse on any goal, better on at least one."],[15.92,20.41,"Now D and K: D is cheaper, but K makes more power."],[20.66,26.27,"Neither wins on both: they are mutually non-dominating."]],"warp":[[0,0],[0.5,0.5],[4.28,3.2],[8.94,6.4],[15.92,9.4],[20.66,12.2],[28.282,15]]},{"dur":18.274,"caps":[[0.5,3.55,"Which layouts does no other layout dominate?"],[3.8,9.09,"Five layouts are each beaten by another one: they turn red."],[9.34,12.47,"The six left over form the Pareto front."],[12.72,17.69,"So the answer is a whole set of layouts, not one best."]],"warp":[[0,0],[0.5,0.5],[3.8,3.2],[9.34,6.4],[12.72,9.4],[18.274,13]]},{"dur":28.329,"caps":[[0.5,7.31,"Twelve solutions, both goals minimised."],[7.56,11.33,"Rank 0: the ones that nobody dominates."],[11.58,16.95,"Set them aside: the next front of what is left is rank 1."],[17.2,22.01,"Keep peeling, like an onion: rank 2, then rank 3."],[22.26,26.43,"Every solution now has a rank: lower is better."]],"warp":[[0,0],[0.5,0.5],[7.56,2.4],[11.58,4.8],[17.2,7.4],[22.26,10.8],[28.329,14]]},{"dur":26.679,"caps":[[0.5,4.51,"Inside one front, which points should we keep?"],[4.76,9.89,"The two ends get infinity: they are always kept."],[10.14,17.03,"For Q, draw a box out to its neighbours P and R: 0.75."],[17.28,21.29,"R and S get bigger boxes: 1.00 and 1.25."],[21.54,25.39,"Prefer the biggest box: it keeps the front spread out."]],"warp":[[0,0],[0.5,0.5],[4.76,3],[10.14,5.4],[17.28,8.6],[21.54,11.2],[26.679,14]]},{"dur":40.101,"caps":[[0.5,5.47,"NSGA-II starts with N = 6 parents."],[5.72,9.17,"They breed six children."],[9.42,12.79,"Parents and children are merged: 12 in all."],[13.04,16.89,"Non-dominated sorting splits the 12 into ranks."],[17.14,22.19,"Rank 0 fits whole: A, B and C are kept."],[22.44,30.53,"Rank 1 has four for three places: crowding drops E."],[30.78,38.15,"The best always survive to the next generation: elitism."]],"warp":[[0,0],[0.5,0.5],[5.72,2.4],[9.42,4.6],[13.04,6.6],[17.14,8.6],[22.44,10.6],[30.78,13.2],[40.101,17]]},{"dur":18.228,"caps":[],"warp":[[0,0],[0.5,0.9],[6.2,2],[11.34,3.1],[18.228,9]]}]};
